export function installAppMenus(d){
 const target=document.getElementById('projectMenuBtn').closest('.menu-anchor'),close=()=>document.querySelectorAll('.app-menu-dropdown').forEach(el=>el.hidden=true);
 const specs=[['file','Fichier',[['new','Nouvelle session','Ctrl+N'],['open','Ouvrir un projet','Ctrl+O'],['save','Enregistrer le projet','Ctrl+S'],['import','Importer audio',''],['export','Exporter / stems','']]],['edit','Édition',[['undo','Annuler','Ctrl+Z'],['redo','Rétablir','Ctrl+Maj+Z'],['cut','Couper le clip','Ctrl+X'],['copy','Copier le clip','Ctrl+C'],['paste','Coller le clip','Ctrl+V'],['duplicate','Dupliquer','Ctrl+D'],['delete','Supprimer','Suppr']]]];
 for(const [id,name,items] of specs){const anchor=document.createElement('div');anchor.className='menu-anchor app-menu-anchor';anchor.innerHTML=`<button class="text-btn" id="${id}MenuBtn" aria-expanded="false" aria-haspopup="menu">${name}</button><div role="menu" class="dropdown app-menu-dropdown" hidden>${items.map(([action,label,key])=>`<button role="menuitem" data-menu-command="${action}"><span>${label}</span><kbd>${key}</kbd></button>`).join('')}</div>`;target.before(anchor);const button=anchor.querySelector('button'),menu=anchor.querySelector('[role=menu]');button.onclick=()=>{const open=menu.hidden;close();menu.hidden=!open;button.setAttribute('aria-expanded',open);if(open)menu.querySelector('button').focus();};menu.onclick=e=>{const b=e.target.closest('[data-menu-command]');if(!b)return;close();d.command(b.dataset.menuCommand);};anchor.onkeydown=e=>{if(e.key==='Escape'){close();button.focus();}if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();const list=[...menu.querySelectorAll('button')],at=list.indexOf(document.activeElement);list[(at+(e.key==='ArrowDown'?1:-1)+list.length)%list.length].focus();}};}
 document.addEventListener('pointerdown',e=>{if(!e.target.closest('.app-menu-anchor'))close();});document.addEventListener('keydown',e=>{if(!(e.ctrlKey||e.metaKey)||e.target.matches('input,textarea,select')||document.getElementById('modal').open)return;const action={s:'save',o:'open',n:'new',x:'cut'}[e.key.toLowerCase()];if(action){e.preventDefault();d.command(action);}},true);
}
